import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaUserCircle, FaCamera, FaArrowLeft, FaSave } from 'react-icons/fa';
import { toast } from 'react-toastify';
import { useAuth } from '../../context/AuthContext';
import profileService from '../../services/profileService';
import Spinner from '../../components/Spinner';
import '../../styles/Profile.css';

const StudentProfile = () => {
    const navigate = useNavigate();
    const { user, updateUser } = useAuth();
    
    const [loading, setLoading] = useState(true);
    const [profileData, setProfileData] = useState({
        name: '',
        email: '',
        phone: '',
        photo: null,
        course: ''
    });
    const [isEditing, setIsEditing] = useState(false);
    const [tempData, setTempData] = useState({ ...profileData });
    const [uploading, setUploading] = useState(false);

    useEffect(() => {
        const fetchProfile = async () => {
            try {
                setLoading(true);
                const profile = await profileService.getProfile();
                const data = {
                    name: profile.name || user?.name || '',
                    email: profile.email || user?.email || '',
                    phone: profile.phone || '',
                    photo: profile.photo || user?.photo || null,
                    course: profile.course || 'Not Enrolled'
                };
                setProfileData(data);
                setTempData(data);
            } catch (error) {
                console.error('Error fetching profile:', error);
                // Use user data from auth context as fallback
                const fallbackData = {
                    name: user?.name || '',
                    email: user?.email || '',
                    phone: '',
                    photo: user?.photo || null,
                    course: user?.course || 'Not Enrolled'
                };
                setProfileData(fallbackData);
                setTempData(fallbackData);
            } finally {
                setLoading(false);
            }
        };

        if (user) {
            fetchProfile();
        }
    }, [user]);

    const handlePhotoUpload = async (e) => {
        const file = e.target.files[0];
        if (file) {
            try {
                setUploading(true);
                
                // Upload to backend
                const response = await profileService.uploadProfilePhoto(file);
                setTempData(prev => ({ ...prev, photo: response.photoUrl }));
                toast.success('Photo uploaded successfully!');
            } catch (error) {
                console.error('Error uploading photo:', error);
                
                // Fallback to local preview
                const reader = new FileReader();
                reader.onloadend = () => {
                    setTempData(prev => ({ ...prev, photo: reader.result }));
                };
                reader.readAsDataURL(file);
                toast.warning('Photo preview only (upload failed)');
            } finally {
                setUploading(false);
            }
        }
    };

    const handlePhoneChange = (e) => {
        const value = e.target.value.replace(/\D/g, '').slice(0, 10);
        setTempData({ ...tempData, phone: value });
    };

    const handleSave = async () => {
        if (tempData.phone && tempData.phone.length !== 10) {
            toast.error("Phone number must be exactly 10 digits.");
            return;
        }

        try {
            setLoading(true);
            
            // Update profile via API
            const updatedProfile = await profileService.updateProfile({
                name: tempData.name,
                phone: tempData.phone,
                photo: tempData.photo
            });
            
            setProfileData(tempData);
            updateUser({ ...user, ...tempData });
            setIsEditing(false);
            toast.success("Profile updated successfully!");
        } catch (error) {
            console.error('Error updating profile:', error);
            
            // Fallback to local storage
            setProfileData(tempData);
            localStorage.setItem('studentProfile', JSON.stringify(tempData));
            setIsEditing(false);
            toast.warning("Profile saved locally only");
        } finally {
            setLoading(false);
        }
    };

    if (loading && !profileData.name) {
        return <Spinner message="Loading profile..." />;
    }

    return (
        <div className="profile-page">
            <div className="profile-header">
                <button className="back-btn" onClick={() => navigate('/student')}>
                    <FaArrowLeft /> Back to Dashboard
                </button>
                <h1>Student Profile</h1>
            </div>

            <div className="profile-card">
                <div className="photo-section">
                    <div className="photo-container">
                        {tempData.photo ? (
                            <img src={tempData.photo} alt="Profile" className="profile-img" />
                        ) : (
                            <FaUserCircle className="profile-placeholder" />
                        )}
                        {isEditing && (
                            <label className="upload-label">
                                <FaCamera />
                                <input type="file" accept="image/*" onChange={handlePhotoUpload} hidden />
                            </label>
                        )}
                    </div>
                </div>

                <div className="info-section">
                    <div className="info-group">
                        <label>Full Name</label>
                        {isEditing ? (
                            <input
                                type="text"
                                value={tempData.name}
                                onChange={(e) => setTempData({ ...tempData, name: e.target.value })}
                                className="edit-input"
                            />
                        ) : (
                            <p className="info-value">{profileData.name}</p>
                        )}
                    </div>

                    <div className="info-group">
                        <label>Email Address</label>
                        {isEditing ? (
                            <input
                                type="email"
                                value={tempData.email}
                                onChange={(e) => setTempData({ ...tempData, email: e.target.value })}
                                className="edit-input"
                            />
                        ) : (
                            <p className="info-value">{profileData.email}</p>
                        )}
                    </div>

                    <div className="info-group">
                        <label>Phone Number</label>
                        {isEditing ? (
                            <input
                                type="tel"
                                value={tempData.phone}
                                onChange={handlePhoneChange}
                                className="edit-input"
                                placeholder="10-digit mobile number"
                            />
                        ) : (
                            <p className="info-value">{profileData.phone}</p>
                        )}
                    </div>

                    <div className="info-group">
                        <label>Enrolled Course</label>
                        <p className="info-value course-tag">{profileData.course}</p>
                    </div>

                    <div className="profile-actions">
                        {isEditing ? (
                            <>
                                <button className="save-btn" onClick={handleSave}>
                                    <FaSave /> Save Changes
                                </button>
                                <button className="cancel-btn" onClick={() => {
                                    setIsEditing(false);
                                    setTempData({ ...profileData });
                                }}>
                                    Cancel
                                </button>
                            </>
                        ) : (
                            <button className="edit-btn" onClick={() => setIsEditing(true)}>
                                Edit Profile
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default StudentProfile;
